INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_ORDER_COMPARE', 'MATH.G8.NUMBER.INTEGERS.INT_IDENTIFY', 'skill', 'essential', 'The sign says which side of zero.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_ORDER_COMPARE', 'MATH.G6.NUMBER.WHOLE_NUMBERS.ORDER_100K', 'skill', 'essential', 'Ordering whole numbers.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_ORDER_COMPARE', 'MATH.G7.MEASUR.TEMPERATURE.TEMP_COMPARE_DIFFERENCE', 'skill', 'helpful', 'Which of two temperatures is colder.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
