INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_IDENTIFY.M_FRACTION_AS_INTEGER', 'MATH.G8.NUMBER.INTEGERS.INT_IDENTIFY', 'Counts fractions and decimals as integers.', '{"question":"Which of -3, 2.5, 0 and 7 are integers?","wrong_answer":"-3, 2.5, 0 and 7","correct_answer":"-3, 0 and 7"}'::jsonb, 'Thinks any number with or without a sign is an integer.', 'The answer -3, 2.5, 0 and 7 as a wrong option, with a reason that names the idea.', 'Integers are whole numbers and their negatives: no parts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_IDENTIFY.M_ZERO_NOT_INTEGER', 'MATH.G8.NUMBER.INTEGERS.INT_IDENTIFY', 'Leaves zero out of the integers, or calls it negative.', '{"question":"Is 0 an integer?","wrong_answer":"No","correct_answer":"Yes"}'::jsonb, 'Thinks integers must be positive or negative.', 'The answer No as a wrong option, with a reason that names the idea.', 'Zero sits between the negatives and the positives and is an integer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_IDENTIFY.M_LOSS_WRITTEN_POSITIVE', 'MATH.G8.NUMBER.INTEGERS.INT_IDENTIFY', 'Writes a loss, a fall or a depth with no minus sign.', '{"question":"A trader loses 200 shillings. Write it as an integer.","wrong_answer":"200","correct_answer":"-200"}'::jsonb, 'Writes the size of the amount and forgets which side of zero it is.', 'The answer 200 as a wrong option, with a reason that names the idea.', 'Decide the direction first: below zero, out or down gets a minus sign.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_IDENTIFY.M_OPPOSITE_SAME_SIGN', 'MATH.G8.NUMBER.INTEGERS.INT_IDENTIFY', 'Gives the opposite of a number with the same sign.', '{"question":"What is the opposite of -6?","wrong_answer":"-6","correct_answer":"6"}'::jsonb, 'Thinks the opposite means a different number on the same side.', 'The answer -6 as a wrong option, with a reason that names the idea.', 'The opposite is the same distance from zero on the other side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_ORDER_COMPARE.M_DIGIT_SIZE_BELOW_ZERO', 'MATH.G8.NUMBER.INTEGERS.INT_ORDER_COMPARE', 'Orders negative numbers by the size of the digits, so -2 is smaller than -9.', '{"question":"Which is smaller, -9 or -2?","wrong_answer":"-2","correct_answer":"-9"}'::jsonb, 'Uses the rule for positive numbers below zero as well.', 'The answer -2 as a wrong option, with a reason that names the idea.', 'Below zero, the further from zero, the smaller: -9 is left of -2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_ORDER_COMPARE.M_NEGATIVES_NOT_COMPARABLE', 'MATH.G8.NUMBER.INTEGERS.INT_ORDER_COMPARE', 'Believes negative numbers cannot be compared with each other.', '{"question":"Put < or > between -4 and -7.","wrong_answer":"They cannot be compared","correct_answer":"-4 > -7"}'::jsonb, 'Has only met comparing counting numbers.', 'The answer They cannot be compared as a wrong option, with a reason that names the idea.', 'Every integer has its own place on the number line; the one further left is smaller.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_ORDER_COMPARE.M_SAME_SIGN_EQUAL', 'MATH.G8.NUMBER.INTEGERS.INT_ORDER_COMPARE', 'Treats two negative numbers as equal because both have a minus sign.', '{"question":"Is -3 equal to -8?","wrong_answer":"Yes, both are negative","correct_answer":"No, -8 < -3"}'::jsonb, 'Looks only at the sign.', 'The answer Yes, both are negative as a wrong option, with a reason that names the idea.', 'The sign says which side of zero; the digits say how far.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_ORDER_COMPARE.M_ORDER_IGNORES_SIGN', 'MATH.G8.NUMBER.INTEGERS.INT_ORDER_COMPARE', 'Orders a mixed list by size of the digits, ignoring signs.', '{"question":"Order -5, 3, -1, 0 from smallest","wrong_answer":"0, -1, 3, -5","correct_answer":"-5, -1, 0, 3"}'::jsonb, 'Drops the signs and sorts the digits.', 'The answer 0, -1, 3, -5 as a wrong option, with a reason that names the idea.', 'Place each number on the number line first, then read from left to right.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_NUMBER_LINE.M_NEGATIVES_ON_RIGHT', 'MATH.G8.NUMBER.INTEGERS.INT_NUMBER_LINE', 'Puts negative numbers to the right of zero.', '{"question":"Mark -3 on a number line from -5 to 5.","wrong_answer":"three steps right of zero","correct_answer":"three steps left of zero"}'::jsonb, 'Writes numbers in the order they are read, not by value.', 'The answer three steps right of zero as a wrong option, with a reason that names the idea.', 'Negative numbers go left of zero (or below it on a vertical line).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_NUMBER_LINE.M_NEGATIVE_LINE_ORDER_REVERSED', 'MATH.G8.NUMBER.INTEGERS.INT_NUMBER_LINE', 'Numbers the left side -1, -2, -3 from the far end instead of from zero.', '{"question":"Complete: -3, __, -1, 0","wrong_answer":"-4","correct_answer":"-2"}'::jsonb, 'Counts the negative side from the left like the positive side.', 'The answer -4 as a wrong option, with a reason that names the idea.', 'Count out from zero both ways: -1 is next to zero.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_NUMBER_LINE.M_UNEQUAL_STEPS', 'MATH.G8.NUMBER.INTEGERS.INT_NUMBER_LINE', 'Spaces the marks unequally, so the numbers do not match the distances.', '{"question":"On a line where each mark is 2, the arrow is 3 marks left of zero.","wrong_answer":"-3","correct_answer":"-6"}'::jsonb, 'Counts marks instead of using the step size.', 'The answer -3 as a wrong option, with a reason that names the idea.', 'Find the step between marks, then multiply by the marks counted.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_NUMBER_LINE.M_ZERO_LEFT_OUT', 'MATH.G8.NUMBER.INTEGERS.INT_NUMBER_LINE', 'Draws the number line with no zero, jumping from -1 to 1.', '{"question":"Complete: -2, -1, __, 1, 2","wrong_answer":"1","correct_answer":"0"}'::jsonb, 'Thinks zero is not a number with a place on the line.', 'The answer 1 as a wrong option, with a reason that names the idea.', 'Zero is the point that separates the two sides; it gets its own mark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_ADD_SUB_LINE.M_SIGN_DROPPED_BELOW_ZERO', 'MATH.G8.NUMBER.INTEGERS.INT_ADD_SUB_LINE', 'Gives the answer as a positive number when the move ends below zero.', '{"question":"A lift at floor 3 goes down 7 floors.","wrong_answer":"4","correct_answer":"-4"}'::jsonb, 'Subtracts the smaller number from the larger and loses the sign.', 'The answer 4 as a wrong option, with a reason that names the idea.', 'Move along the line: past zero you are on the negative side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_ADD_SUB_LINE.M_DOWN_AS_ADD', 'MATH.G8.NUMBER.INTEGERS.INT_ADD_SUB_LINE', 'Moves the wrong way: adds when going down or subtracts when going up.', '{"question":"A lift at floor -2 goes up 5 floors.","wrong_answer":"-7","correct_answer":"3"}'::jsonb, 'Ties the minus sign of the start to the direction of the move.', 'The answer -7 as a wrong option, with a reason that names the idea.', 'Up or add moves right; down or subtract moves left, whatever the start.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_ADD_SUB_LINE.M_START_IGNORED', 'MATH.G8.NUMBER.INTEGERS.INT_ADD_SUB_LINE', 'Gives the size of the move as the answer, ignoring where it started.', '{"question":"A lift at floor 2 goes down 6 floors.","wrong_answer":"-6","correct_answer":"-4"}'::jsonb, 'Reads only the second number.', 'The answer -6 as a wrong option, with a reason that names the idea.', 'Start at the first number, then move.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_ADD_SUB_LINE.M_START_COUNTED_AS_STEP', 'MATH.G8.NUMBER.INTEGERS.INT_ADD_SUB_LINE', 'Counts the starting number as the first step, so lands one step short.', '{"question":"Start at 2 and move 5 steps left.","wrong_answer":"-2","correct_answer":"-3"}'::jsonb, 'Counts marks touched instead of jumps made.', 'The answer -2 as a wrong option, with a reason that names the idea.', 'Count jumps, not marks: the first jump goes from 2 to 1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_ADD_SUB_LINE.M_WRONG_SIDE_OF_ZERO', 'MATH.G8.NUMBER.INTEGERS.INT_ADD_SUB_LINE', 'Gets the right distance from zero but the wrong side.', '{"question":"-6 + 4","wrong_answer":"2","correct_answer":"-2"}'::jsonb, 'Works out 6 - 4 and gives the sign of the second number.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'Check where the move ends: 4 steps right from -6 is still left of zero.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_DIFFERENCE.M_SUBTRACT_ACROSS_ZERO', 'MATH.G8.NUMBER.INTEGERS.INT_DIFFERENCE', 'Subtracts the sizes when the two numbers are on opposite sides of zero.', '{"question":"How much warmer is 9 degrees than -4 degrees?","wrong_answer":"5","correct_answer":"13"}'::jsonb, 'Ignores the minus sign and finds 9 - 4.', 'The answer 5 as a wrong option, with a reason that names the idea.', 'Count up to zero (4) and on to 9 (9 more): add the two parts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_DIFFERENCE.M_ONLY_ONE_SIDE_COUNTED', 'MATH.G8.NUMBER.INTEGERS.INT_DIFFERENCE', 'Counts only the part on one side of zero.', '{"question":"From -4 degrees up to 9 degrees: how much warmer?","wrong_answer":"9","correct_answer":"13"}'::jsonb, 'Starts counting at zero.', 'The answer 9 as a wrong option, with a reason that names the idea.', 'Start at the lower number, not at zero.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_DIFFERENCE.M_DIFFERENCE_NEGATIVE', 'MATH.G8.NUMBER.INTEGERS.INT_DIFFERENCE', 'Gives a difference or a distance as a negative number.', '{"question":"How far apart are -3 and 5?","wrong_answer":"-8","correct_answer":"8"}'::jsonb, 'Subtracts in the wrong order and keeps the sign.', 'The answer -8 as a wrong option, with a reason that names the idea.', 'A distance apart is always positive: larger minus smaller.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_DIFFERENCE.M_SEA_LEVEL_DEPTH_ADDED_WRONG', 'MATH.G8.NUMBER.INTEGERS.INT_DIFFERENCE', 'Subtracts a depth below sea level from a height above it instead of adding.', '{"question":"A hill 120 m above sea level and a well 30 m below. Height from the bottom of the well to the top?","wrong_answer":"90 m","correct_answer":"150 m"}'::jsonb, 'Sees two numbers and takes the smaller away.', 'The answer 90 m as a wrong option, with a reason that names the idea.', 'Draw the vertical line: the well is below zero, the hill above, so the two parts add.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_COMBINED_CONTEXT.M_OPENING_BALANCE_LEFT_OUT', 'MATH.G8.NUMBER.INTEGERS.INT_COMBINED_CONTEXT', 'Adds up the changes and leaves out the starting balance.', '{"question":"Start 500 shillings; changes +200, -150, -100. Balance?","wrong_answer":"-50","correct_answer":"450"}'::jsonb, 'Treats the changes as the whole story.', 'The answer -50 as a wrong option, with a reason that names the idea.', 'Start from the opening balance and apply each change.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_COMBINED_CONTEXT.M_MINUS_ADDED', 'MATH.G8.NUMBER.INTEGERS.INT_COMBINED_CONTEXT', 'Adds amounts with a minus sign as if they were money in.', '{"question":"Start 500; changes +200, -150, -100. Balance?","wrong_answer":"950","correct_answer":"450"}'::jsonb, 'Ignores the signs in the table.', 'The answer 950 as a wrong option, with a reason that names the idea.', 'A minus sign means money went out: take it away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_COMBINED_CONTEXT.M_ONLY_GAINS_COUNTED', 'MATH.G8.NUMBER.INTEGERS.INT_COMBINED_CONTEXT', 'Uses only the positive changes and drops the negative ones.', '{"question":"Start 500; changes +200, -150, -100. Balance?","wrong_answer":"700","correct_answer":"450"}'::jsonb, 'Thinks the minus amounts do not count.', 'The answer 700 as a wrong option, with a reason that names the idea.', 'Every change in the table counts, in or out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_COMBINED_CONTEXT.M_SIGN_OF_CHANGE_DROPPED', 'MATH.G8.NUMBER.INTEGERS.INT_COMBINED_CONTEXT', 'Writes a fall or a drop as a positive change.', '{"question":"The temperature falls 18 degrees in 6 hours. Change each hour?","wrong_answer":"3","correct_answer":"-3"}'::jsonb, 'Gives the size of the change only.', 'The answer 3 as a wrong option, with a reason that names the idea.', 'A fall is a negative change: keep the minus sign.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_COMBINED_CONTEXT.M_FINAL_FOR_CHANGE', 'MATH.G8.NUMBER.INTEGERS.INT_COMBINED_CONTEXT', 'Divides the final reading by the number of steps instead of the total change.', '{"question":"From 6 degrees it falls the same each hour for 4 hours to -10 degrees. Change each hour?","wrong_answer":"-2.5","correct_answer":"-4"}'::jsonb, 'Uses the reading at the end as if it were the change.', 'The answer -2.5 as a wrong option, with a reason that names the idea.', 'Find the total change first (end minus start), then share it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_COMBINED_CONTEXT.M_TOTAL_NOT_SHARED', 'MATH.G8.NUMBER.INTEGERS.INT_COMBINED_CONTEXT', 'Gives the whole change when the change for each step is asked.', '{"question":"A fall of 16 degrees over 4 hours. Change each hour?","wrong_answer":"-16","correct_answer":"-4"}'::jsonb, 'Stops after finding the total.', 'The answer -16 as a wrong option, with a reason that names the idea.', 'Each hour gets an equal share: divide by the hours.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_COMBINED_CONTEXT.M_STEPS_ADDED_NOT_MULTIPLIED', 'MATH.G8.NUMBER.INTEGERS.INT_COMBINED_CONTEXT', 'Adds the number of steps to the change instead of multiplying.', '{"question":"The level falls 3 m a month for 5 months. Total change?","wrong_answer":"-8","correct_answer":"-15"}'::jsonb, 'Combines the two numbers by adding.', 'The answer -8 as a wrong option, with a reason that names the idea.', '5 months of -3 each is 5 lots of -3: multiply.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_COMBINED_CONTEXT.M_DEEPER_AS_LESS_NEGATIVE', 'MATH.G8.NUMBER.INTEGERS.INT_COMBINED_CONTEXT', 'Makes a level less negative when it goes further down.', '{"question":"A level at -4 m falls 6 m. New level?","wrong_answer":"2","correct_answer":"-10"}'::jsonb, 'Adds the fall to the negative number as if it moved up.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'Going down moves left on the line: -4 - 6 = -10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_COMBINED_CONTEXT.M_START_NOT_REMOVED', 'MATH.G8.NUMBER.INTEGERS.INT_COMBINED_CONTEXT', 'Works out how many steps a total takes without first taking away the starting amount.', '{"question":"Water at 10 m deep falls 4 m a month. Months until it is 30 m deep?","wrong_answer":"7.5","correct_answer":"5"}'::jsonb, 'Divides the final depth by the change each month.', 'The answer 7.5 as a wrong option, with a reason that names the idea.', 'The extra depth is 30 - 10; divide that by 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_COMBINED_CONTEXT.M_RATE_OPERATION_WRONG', 'MATH.G8.NUMBER.INTEGERS.INT_COMBINED_CONTEXT', 'Adds or subtracts the number of steps where it should divide or multiply by it.', '{"question":"A fall of 12 degrees over 4 hours. Change each hour?","wrong_answer":"-8","correct_answer":"-3"}'::jsonb, 'Picks the operation from the size of the numbers.', 'The answer -8 as a wrong option, with a reason that names the idea.', 'Ask: is the total shared out (divide) or built up (multiply)?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_ORDER_OF_OPERATIONS.M_LEFT_TO_RIGHT', 'MATH.G8.NUMBER.FRACTIONS.FRAC_ORDER_OF_OPERATIONS', 'Works from left to right, subtracting before dividing.', '{"question":"3/4 - 1/2 ÷ 2","wrong_answer":"1/8","correct_answer":"1/2"}'::jsonb, 'Reads the question like a sentence.', 'The answer 1/8 as a wrong option, with a reason that names the idea.', 'Divide and multiply first, then add and subtract.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_ORDER_OF_OPERATIONS.M_DIVIDE_NOT_INVERTED', 'MATH.G8.NUMBER.FRACTIONS.FRAC_ORDER_OF_OPERATIONS', 'Multiplies by the divisor as it is instead of by its reciprocal.', '{"question":"1/2 ÷ 2/3","wrong_answer":"1/3","correct_answer":"3/4"}'::jsonb, 'Remembers "multiply" but not "turn the second one upside down".', 'The answer 1/3 as a wrong option, with a reason that names the idea.', 'Dividing by 2/3 is multiplying by 3/2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_ORDER_OF_OPERATIONS.M_WRONG_ONE_INVERTED', 'MATH.G8.NUMBER.FRACTIONS.FRAC_ORDER_OF_OPERATIONS', 'Turns the first fraction upside down instead of the divisor.', '{"question":"2/5 ÷ 3/4","wrong_answer":"15/8","correct_answer":"8/15"}'::jsonb, 'Inverts whichever fraction comes first.', 'The answer 15/8 as a wrong option, with a reason that names the idea.', 'Only the fraction you divide by is turned over.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_ORDER_OF_OPERATIONS.M_ADD_TOPS_AND_BOTTOMS', 'MATH.G8.NUMBER.FRACTIONS.FRAC_ORDER_OF_OPERATIONS', 'Adds or subtracts numerators and denominators straight across.', '{"question":"1/2 + 1/3","wrong_answer":"2/5","correct_answer":"5/6"}'::jsonb, 'Copies the rule for multiplying.', 'The answer 2/5 as a wrong option, with a reason that names the idea.', 'Use a common denominator, then add the numerators.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_ORDER_OF_OPERATIONS.M_NOT_SIMPLIFIED', 'MATH.G8.NUMBER.FRACTIONS.FRAC_ORDER_OF_OPERATIONS', 'Leaves the answer not in its simplest form.', '{"question":"1/4 + 1/4 × 1/2 in simplest form","wrong_answer":"6/16","correct_answer":"3/8"}'::jsonb, 'Stops after the last operation.', 'The answer 6/16 as a wrong option, with a reason that names the idea.', 'Divide top and bottom by their HCF.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_BRACKETS_AND_OF.M_BRACKET_IGNORED', 'MATH.G8.NUMBER.FRACTIONS.FRAC_BRACKETS_AND_OF', 'Works the question without doing the bracket first.', '{"question":"(1/2 + 1/3) × 3/5","wrong_answer":"7/10","correct_answer":"1/2"}'::jsonb, 'Applies multiplication first everywhere.', 'The answer 7/10 as a wrong option, with a reason that names the idea.', 'Brackets come before everything else.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_BRACKETS_AND_OF.M_OF_AS_ADD', 'MATH.G8.NUMBER.FRACTIONS.FRAC_BRACKETS_AND_OF', 'Treats "of" as adding or as taking away.', '{"question":"2/3 of 3/4","wrong_answer":"17/12","correct_answer":"1/2"}'::jsonb, 'Reads "of" as "and".', 'The answer 17/12 as a wrong option, with a reason that names the idea.', '"Of" means multiply.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_BRACKETS_AND_OF.M_OF_DONE_LAST', 'MATH.G8.NUMBER.FRACTIONS.FRAC_BRACKETS_AND_OF', 'Does the addition before the "of".', '{"question":"2/3 of 3/4 + 1/4","wrong_answer":"2/3","correct_answer":"3/4"}'::jsonb, 'Thinks "of" is the last step because it is a word.', 'The answer 2/3 as a wrong option, with a reason that names the idea.', '"Of" is multiplication: it comes before adding.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_BRACKETS_AND_OF.M_BRACKET_PARTLY_MULTIPLIED', 'MATH.G8.NUMBER.FRACTIONS.FRAC_BRACKETS_AND_OF', 'Multiplies only the first fraction in the bracket.', '{"question":"3/5 × (1/2 + 1/3)","wrong_answer":"3/10 + 1/3 = 19/30","correct_answer":"1/2"}'::jsonb, 'Treats the bracket as if it were not there.', 'The answer 3/10 + 1/3 = 19/30 as a wrong option, with a reason that names the idea.', 'Work out the bracket to one fraction first, then multiply.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_MIXED_COMBINED.M_WHOLE_AND_FRACTION_SEPARATE_MULTIPLY', 'MATH.G8.NUMBER.FRACTIONS.FRAC_MIXED_COMBINED', 'Multiplies whole parts together and fractions together.', '{"question":"1 1/2 × 2 1/3","wrong_answer":"2 1/6","correct_answer":"3 1/2"}'::jsonb, 'Treats a mixed number as two separate numbers.', 'The answer 2 1/6 as a wrong option, with a reason that names the idea.', 'Change both to improper fractions first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_MIXED_COMBINED.M_WHOLE_PART_DROPPED', 'MATH.G8.NUMBER.FRACTIONS.FRAC_MIXED_COMBINED', 'Leaves out the whole number part of a mixed number.', '{"question":"1 1/2 × 2/3","wrong_answer":"1/3","correct_answer":"1"}'::jsonb, 'Works only with the fraction.', 'The answer 1/3 as a wrong option, with a reason that names the idea.', 'The whole part counts: 1 1/2 is 3/2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_MIXED_COMBINED.M_IMPROPER_WRONG', 'MATH.G8.NUMBER.FRACTIONS.FRAC_MIXED_COMBINED', 'Changes a mixed number to an improper fraction wrongly (adds the whole to the numerator).', '{"question":"2 1/3 as an improper fraction","wrong_answer":"3/3","correct_answer":"7/3"}'::jsonb, 'Adds instead of multiplying the whole by the denominator.', 'The answer 3/3 as a wrong option, with a reason that names the idea.', 'Whole times denominator, plus the numerator.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_MIXED_COMBINED.M_ANSWER_LEFT_IMPROPER', 'MATH.G8.NUMBER.FRACTIONS.FRAC_MIXED_COMBINED', 'Leaves the answer as an improper fraction when a mixed number is asked.', '{"question":"Give 1 1/2 × 2/3 + 1/4 as a mixed number","wrong_answer":"5/4","correct_answer":"1 1/4"}'::jsonb, 'Stops once the arithmetic is done.', 'The answer 5/4 as a wrong option, with a reason that names the idea.', 'Divide the numerator by the denominator: the remainder is the fraction.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_REST_OF_WHOLE.M_PARTS_GIVEN_FOR_REST', 'MATH.G8.NUMBER.FRACTIONS.FRAC_REST_OF_WHOLE', 'Gives the part used as the answer for the part left.', '{"question":"A shamba of 12 acres: 1/3 maize, 1/4 beans. Acres of grass?","wrong_answer":"7","correct_answer":"5"}'::jsonb, 'Finds the fractions used and stops.', 'The answer 7 as a wrong option, with a reason that names the idea.', 'The rest is the whole minus what is used.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_REST_OF_WHOLE.M_ONE_PART_TAKEN_AWAY', 'MATH.G8.NUMBER.FRACTIONS.FRAC_REST_OF_WHOLE', 'Takes away only one of the fractions used.', '{"question":"A shamba of 12 acres: 1/3 maize, 1/4 beans. Acres of grass?","wrong_answer":"8","correct_answer":"5"}'::jsonb, 'Forgets that each activity uses its own share.', 'The answer 8 as a wrong option, with a reason that names the idea.', 'Take away every part used.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_REST_OF_WHOLE.M_FRACTIONS_OF_SAME_WHOLE_MULTIPLIED', 'MATH.G8.NUMBER.FRACTIONS.FRAC_REST_OF_WHOLE', 'Multiplies two fractions or amounts of the same whole instead of adding them.', '{"question":"12 acres: 1/3 maize, 1/4 beans. Acres with crops?","wrong_answer":"12","correct_answer":"7"}'::jsonb, 'Sees two fractions and multiplies.', 'The answer 12 as a wrong option, with a reason that names the idea.', 'Both are fractions of the same shamba: add them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_REST_OF_WHOLE.M_UNIT_NOT_CONVERTED', 'MATH.G8.NUMBER.FRACTIONS.FRAC_REST_OF_WHOLE', 'Gives the answer in the wrong unit (hours when minutes are asked).', '{"question":"A day of 8 hours; 1/4 is left for clubs. Minutes for clubs?","wrong_answer":"2","correct_answer":"120"}'::jsonb, 'Works with the number given and forgets the unit asked.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'Change 8 hours to 480 minutes first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_REST_OF_WHOLE.M_REST_AS_FRACTION_ONLY', 'MATH.G8.NUMBER.FRACTIONS.FRAC_REST_OF_WHOLE', 'Gives the fraction left when the amount is asked.', '{"question":"12 acres; 5/12 is grass. How many acres?","wrong_answer":"5/12","correct_answer":"5"}'::jsonb, 'Stops at the fraction.', 'The answer 5/12 as a wrong option, with a reason that names the idea.', 'Find that fraction of the whole quantity.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_OF_REMAINDER.M_EMPTY_SPACE_FOR_CONTENTS', 'MATH.G8.NUMBER.FRACTIONS.FRAC_OF_REMAINDER', 'Gives the empty part when the amount in the container is asked.', '{"question":"A 6,000 litre tank is 3/4 full. Litres in it?","wrong_answer":"1,500","correct_answer":"4,500"}'::jsonb, 'Takes the fraction away instead of finding it.', 'The answer 1,500 as a wrong option, with a reason that names the idea.', '3/4 full means 3/4 of 6,000 is water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_OF_REMAINDER.M_FRACTION_OF_WHOLE_NOT_REMAINDER', 'MATH.G8.NUMBER.FRACTIONS.FRAC_OF_REMAINDER', 'Takes the second fraction of the whole instead of what is left.', '{"question":"6,000 litres, 3/4 full; 1/3 of the water is used. Litres used?","wrong_answer":"2,000","correct_answer":"1,500"}'::jsonb, 'Does not see that "of the water" means of what is there.', 'The answer 2,000 as a wrong option, with a reason that names the idea.', 'Find what is there first, then the fraction of it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_OF_REMAINDER.M_USED_FOR_LEFT', 'MATH.G8.NUMBER.FRACTIONS.FRAC_OF_REMAINDER', 'Gives the amount used when the amount left is asked.', '{"question":"4,500 litres; 1/3 is used. Litres left?","wrong_answer":"1,500","correct_answer":"3,000"}'::jsonb, 'Stops after the first calculation.', 'The answer 1,500 as a wrong option, with a reason that names the idea.', 'Left = what was there minus what was used.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_OF_REMAINDER.M_FRACTIONS_SUBTRACTED', 'MATH.G8.NUMBER.FRACTIONS.FRAC_OF_REMAINDER', 'Subtracts the two fractions as if they were of the same whole.', '{"question":"3/4 full, then 1/3 of the water used. Fraction of the tank left?","wrong_answer":"5/12","correct_answer":"1/2"}'::jsonb, 'Treats 1/3 of the water as 1/3 of the tank.', 'The answer 5/12 as a wrong option, with a reason that names the idea.', '1/3 of 3/4 is 1/4 of the tank; 3/4 - 1/4 = 1/2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_SHOPPING_CONTEXT.M_DIVIDE_FOR_COST', 'MATH.G8.NUMBER.FRACTIONS.FRAC_SHOPPING_CONTEXT', 'Divides the price by the fraction to find the cost of part of a unit.', '{"question":"3/4 kg of meat at 600 shillings a kg","wrong_answer":"800","correct_answer":"450"}'::jsonb, 'Picks the operation that makes the number bigger.', 'The answer 800 as a wrong option, with a reason that names the idea.', 'Part of a kilogram costs part of the price: multiply.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_SHOPPING_CONTEXT.M_MULTIPLY_FOR_HOW_MANY', 'MATH.G8.NUMBER.FRACTIONS.FRAC_SHOPPING_CONTEXT', 'Multiplies to find how many fractional pieces fit.', '{"question":"6 m of cloth cut into pieces of 3/4 m. How many?","wrong_answer":"4 1/2","correct_answer":"8"}'::jsonb, 'Sees "pieces of" and multiplies.', 'The answer 4 1/2 as a wrong option, with a reason that names the idea.', 'How many fit means divide: 6 ÷ 3/4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_SHOPPING_CONTEXT.M_REMAINDER_PIECE_COUNTED', 'MATH.G8.NUMBER.FRACTIONS.FRAC_SHOPPING_CONTEXT', 'Counts a part piece as a whole piece.', '{"question":"5 m of ribbon into pieces of 2/3 m. Whole pieces?","wrong_answer":"8","correct_answer":"7"}'::jsonb, 'Rounds up the answer.', 'The answer 8 as a wrong option, with a reason that names the idea.', 'Only whole pieces count: 7 1/2 gives 7.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_SHOPPING_CONTEXT.M_SHARE_BY_DENOMINATOR', 'MATH.G8.NUMBER.FRACTIONS.FRAC_SHOPPING_CONTEXT', 'Divides by the denominator only when sharing by a fraction.', '{"question":"A trader keeps 2/5 of 1,000 shillings. How much?","wrong_answer":"200","correct_answer":"400"}'::jsonb, 'Finds one fifth and stops.', 'The answer 200 as a wrong option, with a reason that names the idea.', 'Find one fifth, then take two of them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.FRACTION_TO_DECIMAL.M_DIGITS_AS_DECIMAL', 'MATH.G8.NUMBER.DECIMALS.FRACTION_TO_DECIMAL', 'Writes the numerator and denominator side by side as a decimal.', '{"question":"3/8 as a decimal","wrong_answer":"3.8","correct_answer":"0.375"}'::jsonb, 'Thinks the fraction line is a decimal point.', 'The answer 3.8 as a wrong option, with a reason that names the idea.', 'A fraction is a division: 3 ÷ 8.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.FRACTION_TO_DECIMAL.M_DIVIDE_WRONG_WAY', 'MATH.G8.NUMBER.DECIMALS.FRACTION_TO_DECIMAL', 'Divides the denominator by the numerator.', '{"question":"3/8 as a decimal","wrong_answer":"2.667","correct_answer":"0.375"}'::jsonb, 'Divides the larger number by the smaller.', 'The answer 2.667 as a wrong option, with a reason that names the idea.', 'Top divided by bottom: a proper fraction is less than 1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
