INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.RECURRING_IDENTIFY.M_PROPER_FRACTION_RECURS', 'MATH.G8.NUMBER.DECIMALS.RECURRING_IDENTIFY', 'Believes a fraction recurs because the top is smaller than the bottom.', '{"question":"Does 3/4 give a recurring decimal?","wrong_answer":"Yes, 3 is less than 4","correct_answer":"No: 0.75"}'::jsonb, 'Links recurring with proper fractions.', 'The answer Yes, 3 is less than 4 as a wrong option, with a reason that names the idea.', 'Look at the prime factors of the denominator: 4 = 2 × 2 stops.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
