INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.STANDARD_FORM.M_FRONT_NOT_ADJUSTED', 'MATH.G8.NUMBER.DECIMALS.STANDARD_FORM', 'Leaves a product front number of 10 or more without moving a 10 into the power.', '{"question":"(4 × 10³) × (5 × 10²)","wrong_answer":"20 × 10⁵","correct_answer":"2 × 10⁶"}'::jsonb, 'Does not check the front number at the end.', 'The answer 20 × 10⁵ as a wrong option, with a reason that names the idea.', '20 = 2 × 10: one more power of 10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.STANDARD_FORM.M_ZEROS_MISCOUNTED', 'MATH.G8.NUMBER.DECIMALS.STANDARD_FORM', 'Writes the ordinary number with the wrong number of zeros.', '{"question":"2 × 10⁶ as an ordinary number","wrong_answer":"20,000,000","correct_answer":"2,000,000"}'::jsonb, 'Writes as many zeros as the power plus one.', 'The answer 20,000,000 as a wrong option, with a reason that names the idea.', 'Move the point 6 places right from 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.DEC_COMBINED_OPERATIONS.M_POINT_PLACES_PRODUCT', 'MATH.G8.NUMBER.DECIMALS.DEC_COMBINED_OPERATIONS', 'Puts the point in a product by copying one number''s decimal places.', '{"question":"0.4 × 1.3","wrong_answer":"5.2","correct_answer":"0.52"}'::jsonb, 'Counts the places in one number only.', 'The answer 5.2 as a wrong option, with a reason that names the idea.', 'Add the decimal places of both numbers: 1 + 1 = 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
