INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.DEC_COMBINED_OPERATIONS.M_DEC_ALL_ADDED', 'MATH.G8.NUMBER.DECIMALS.DEC_COMBINED_OPERATIONS', 'Adds all the numbers whatever the signs.', '{"question":"2.5 + 0.4 × 1.3","wrong_answer":"4.2","correct_answer":"3.02"}'::jsonb, 'Ignores the operation signs.', 'The answer 4.2 as a wrong option, with a reason that names the idea.', 'Read each sign: × multiplies.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.DEC_COMBINED_OPERATIONS.M_POINTS_NOT_LINED_UP', 'MATH.G8.NUMBER.DECIMALS.DEC_COMBINED_OPERATIONS', 'Lines up the last digits instead of the points when adding.', '{"question":"2.5 + 0.52","wrong_answer":"0.77","correct_answer":"3.02"}'::jsonb, 'Adds like whole numbers from the right.', 'The answer 0.77 as a wrong option, with a reason that names the idea.', 'Line up the points: tenths under tenths.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.DEC_COMBINED_OPERATIONS.M_DIVISOR_POINT_NOT_MOVED', 'MATH.G8.NUMBER.DECIMALS.DEC_COMBINED_OPERATIONS', 'Divides by a decimal without making the divisor a whole number.', '{"question":"1.2 ÷ 0.3","wrong_answer":"0.4","correct_answer":"4"}'::jsonb, 'Divides 1.2 by 3.', 'The answer 0.4 as a wrong option, with a reason that names the idea.', 'Multiply both by 10: 12 ÷ 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.DEC_REAL_LIFE.M_INCOME_FOR_PROFIT', 'MATH.G8.NUMBER.DECIMALS.DEC_REAL_LIFE', 'Gives the money from selling as the profit.', '{"question":"5 dresses sold at 900 shillings, cloth 2.5 m at 120 a metre each. Profit?","wrong_answer":"4,500","correct_answer":"3,000"}'::jsonb, 'Forgets to take away what was spent.', 'The answer 4,500 as a wrong option, with a reason that names the idea.', 'Profit = money in minus money spent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.DEC_REAL_LIFE.M_COST_FOR_PROFIT', 'MATH.G8.NUMBER.DECIMALS.DEC_REAL_LIFE', 'Gives the total cost as the profit.', '{"question":"5 dresses at 900, cloth 2.5 m at 120 each. Profit?","wrong_answer":"1,500","correct_answer":"3,000"}'::jsonb, 'Finds the cost and stops.', 'The answer 1,500 as a wrong option, with a reason that names the idea.', 'The cost is taken away from the sales.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
