INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.DEC_REAL_LIFE.M_RATE_FOR_ITEM_COST', 'MATH.G8.NUMBER.DECIMALS.DEC_REAL_LIFE', 'Uses the price of one metre as the cost of one item.', '{"question":"A dress uses 2.5 m at 120 shillings a metre. Cloth cost of a dress?","wrong_answer":"120","correct_answer":"300"}'::jsonb, 'Uses the rate without the quantity.', 'The answer 120 as a wrong option, with a reason that names the idea.', 'Cost = length × price a metre.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.DEC_REAL_LIFE.M_COST_FOR_CHANGE', 'MATH.G8.NUMBER.DECIMALS.DEC_REAL_LIFE', 'Gives the total cost when the change is asked.', '{"question":"3 pens at 45.50 shillings, paid with 200. Change?","wrong_answer":"136.50","correct_answer":"63.50"}'::jsonb, 'Stops at the total cost.', 'The answer 136.50 as a wrong option, with a reason that names the idea.', 'Change = money paid minus the cost.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
