INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.ROOT_BETWEEN_SQUARES.M_NUMBER_NOT_ROOT_COMPARED', 'MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.ROOT_BETWEEN_SQUARES', 'Places the root by the number itself, not by squares.', '{"question":"Why is √55 between 7 and 8?","wrong_answer":"55 is between 7 and 8","correct_answer":"49 < 55 < 64"}'::jsonb, 'Compares the number with the ends directly.', 'The answer 55 is between 7 and 8 as a wrong option, with a reason that names the idea.', 'Square the ends: 7² = 49 and 8² = 64.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
