INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_COMPARE.M_SHARE_BY_PART_NOT_WHOLE', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_COMPARE', 'Compares a part with the other part instead of with the whole class.', '{"question":"Girls : boys 2 : 3 in 8A and 3 : 5 in 8B. Bigger share of girls?","wrong_answer":"8B","correct_answer":"8A"}'::jsonb, 'Thinks the bigger girl number gives the bigger share.', 'The answer 8B as a wrong option, with a reason that names the idea.', 'Girls out of the whole: 2/5 and 3/8.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_SHARE.M_SHARE_FOR_DIFFERENCE', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_SHARE', 'Gives one share when the difference between two shares is asked.', '{"question":"9,000 in 2 : 3 : 4. How much more does the third get than the first?","wrong_answer":"4,000","correct_answer":"2,000"}'::jsonb, 'Stops at the share.', 'The answer 4,000 as a wrong option, with a reason that names the idea.', 'Take the first share from the third.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_SHARE.M_PARTS_NOT_VALUED', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_SHARE', 'Gives the difference in parts, not in shillings.', '{"question":"9,000 in 2 : 3 : 4. How much more does the third get than the first?","wrong_answer":"2","correct_answer":"2,000"}'::jsonb, 'Forgets each part has a value.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'One part is 9,000 ÷ 9 = 1,000.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_SHARE.M_WRONG_PEOPLE_COMPARED', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_SHARE', 'Compares the wrong two shares.', '{"question":"9,000 in 2 : 3 : 4. Third more than first?","wrong_answer":"1,000","correct_answer":"2,000"}'::jsonb, 'Reads the neighbouring share.', 'The answer 1,000 as a wrong option, with a reason that names the idea.', 'Check which two people the question names.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_SHARE.M_DIVIDE_BY_OWN_PART', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_SHARE', 'Divides the total by one person''s parts instead of all the parts.', '{"question":"9,000 in 2 : 3 : 4. Share of the third?","wrong_answer":"2,250","correct_answer":"4,000"}'::jsonb, 'Uses only that person''s number.', 'The answer 2,250 as a wrong option, with a reason that names the idea.', 'Divide by all the parts: 2 + 3 + 4 = 9.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_SHARE.M_ONE_GROUP_ONLY', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_SHARE', 'Gives one group when the total is asked.', '{"question":"Goats : sheep = 3 : 4 and there are 20 sheep. Animals altogether?","wrong_answer":"15","correct_answer":"35"}'::jsonb, 'Finds the goats and stops.', 'The answer 15 as a wrong option, with a reason that names the idea.', 'Add the sheep.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_SHARE.M_RATIO_NUMBER_AS_COUNT', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_SHARE', 'Uses the ratio number as the actual number.', '{"question":"Goats : sheep = 3 : 4, 20 sheep. Altogether?","wrong_answer":"23","correct_answer":"35"}'::jsonb, 'Thinks 3 goats because the ratio says 3.', 'The answer 23 as a wrong option, with a reason that names the idea.', 'One part = 20 ÷ 4 = 5, so 15 goats.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_SHARE.M_GIVEN_AMOUNT_AS_PART', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_SHARE', 'Treats the known share as one part.', '{"question":"Goats : sheep = 3 : 4, 20 sheep. Altogether?","wrong_answer":"140","correct_answer":"35"}'::jsonb, 'Multiplies the known amount by all the parts.', 'The answer 140 as a wrong option, with a reason that names the idea.', 'The 20 sheep are 4 parts: find one part first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_WORK_OUT.M_PART_TO_WHOLE', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_WORK_OUT', 'Compares a part with the whole instead of with the other part.', '{"question":"A 3 m rope cut so the short piece is 25 cm. Short : long as 1 : n?","wrong_answer":"1 : 12","correct_answer":"1 : 11"}'::jsonb, 'Uses the whole rope as the second term.', 'The answer 1 : 12 as a wrong option, with a reason that names the idea.', 'The long piece is 300 - 25 = 275 cm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_WORK_OUT.M_CM_IN_M_WRONG', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_WORK_OUT', 'Uses 1,000 cm in a metre.', '{"question":"3 m in centimetres","wrong_answer":"3,000","correct_answer":"300"}'::jsonb, 'Mixes up cm with mm.', 'The answer 3,000 as a wrong option, with a reason that names the idea.', '100 cm make 1 m.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
