INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PERCENT_CHANGE_REVERSE.M_PCT_DIVIDED_BY_PCT', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PERCENT_CHANGE_REVERSE', 'Divides the new price by the percentage change.', '{"question":"After a 20% rise a price is 960. Price before?","wrong_answer":"48","correct_answer":"800"}'::jsonb, 'Divides by the only other number.', 'The answer 48 as a wrong option, with a reason that names the idea.', 'Divide by 120 to find 1%, then times 100.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_IDENTIFY.M_DIRECT_AS_INVERSE', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_IDENTIFY', 'Calls a direct proportion inverse, or the other way round.', '{"question":"Kilograms of sugar and the cost: direct or inverse?","wrong_answer":"inverse","correct_answer":"direct"}'::jsonb, 'Does not test what happens when one doubles.', 'The answer inverse as a wrong option, with a reason that names the idea.', 'Double the sugar: the cost doubles, so direct.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_IDENTIFY.M_ANY_LINK_AS_PROPORTION', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_IDENTIFY', 'Calls two quantities in proportion just because both grow.', '{"question":"The age of a child and the height of the child","wrong_answer":"direct proportion","correct_answer":"neither"}'::jsonb, 'Thinks "both go up" is enough.', 'The answer direct proportion as a wrong option, with a reason that names the idea.', 'Proportion needs a fixed rule: double one, double the other.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_IDENTIFY.M_DECREASE_AS_INVERSE', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_IDENTIFY', 'Calls it inverse when one quantity goes down, whatever the rule.', '{"question":"Litres of petrol used and litres left in a 50 litre tank","wrong_answer":"inverse proportion","correct_answer":"neither"}'::jsonb, 'Thinks "one up, one down" means inverse.', 'The answer inverse proportion as a wrong option, with a reason that names the idea.', 'Inverse means the product stays the same: double one, halve the other.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_IDENTIFY.M_UNLINKED_AS_PROPORTION', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_IDENTIFY', 'Gives a proportion for two quantities that are not linked at all.', '{"question":"Learners in a class and the height of the classroom","wrong_answer":"direct","correct_answer":"neither"}'::jsonb, 'Assumes every pair in a question is linked.', 'The answer direct as a wrong option, with a reason that names the idea.', 'Ask: does changing one change the other at all?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_SOLVE.M_INVERSE_AS_DIRECT', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_SOLVE', 'Uses direct proportion for an inverse situation.', '{"question":"6 workers take 10 days. 4 workers take?","wrong_answer":"6.7 days","correct_answer":"15 days"}'::jsonb, 'Multiplies by the ratio of workers.', 'The answer 6.7 days as a wrong option, with a reason that names the idea.', 'Fewer workers take more days: total work 60 worker-days.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_SOLVE.M_TOTAL_WORK_GIVEN', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_SOLVE', 'Gives the total worker-days as the answer.', '{"question":"6 workers take 10 days. 4 workers take?","wrong_answer":"60","correct_answer":"15 days"}'::jsonb, 'Stops after finding the total work.', 'The answer 60 as a wrong option, with a reason that names the idea.', 'Share the 60 worker-days among 4 workers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_SOLVE.M_PROPORTION_ADDED', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_SOLVE', 'Adds or subtracts the change in workers to the days.', '{"question":"6 workers take 10 days. 4 workers take?","wrong_answer":"8","correct_answer":"15 days"}'::jsonb, 'Links the numbers by adding.', 'The answer 8 as a wrong option, with a reason that names the idea.', 'Workers and days multiply to a fixed total.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_SOLVE.M_PRODUCT_ROW_CHECK_MISSED', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_SOLVE', 'Checks a table of inverse proportion by differences instead of products.', '{"question":"Workers 2, 4, 5, 8; days 20, 10, 9, 5. Which row is wrong?","wrong_answer":"8 workers","correct_answer":"5 workers (5 × 9 = 45, not 40)"}'::jsonb, 'Looks for a steady difference.', 'The answer 8 workers as a wrong option, with a reason that names the idea.', 'In inverse proportion, workers × days is the same in every row.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_HCF.M_COMMON_FACTOR_NOT_HIGHEST', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_HCF', 'Takes out a common factor that is not the highest.', '{"question":"Factorise 12x + 18 fully","wrong_answer":"3(4x + 6)","correct_answer":"6(2x + 3)"}'::jsonb, 'Stops at the first common factor found.', 'The answer 3(4x + 6) as a wrong option, with a reason that names the idea.', 'Check the bracket: 4x + 6 still has a factor 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_HCF.M_INSIDE_COEFFICIENT_GIVEN', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_HCF', 'Gives the number left in front of x inside the bracket as the factor outside.', '{"question":"12x + 18 = ?(2x + 3). The number outside?","wrong_answer":"2","correct_answer":"6"}'::jsonb, 'Mixes up the factor with what is left.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'The factor outside multiplies to give 12 and 18.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_HCF.M_INSIDE_NUMBER_GIVEN', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_HCF', 'Gives the number left in the bracket as the factor outside.', '{"question":"12x + 18 = ?(2x + 3). The number outside?","wrong_answer":"3","correct_answer":"6"}'::jsonb, 'Reads the wrong number from the answer.', 'The answer 3 as a wrong option, with a reason that names the idea.', 'Outside × inside must give back each term.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_HCF.M_FACTOR_ONE_TERM_ONLY', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_HCF', 'Divides only the first term by the factor.', '{"question":"Factorise 6x + 9","wrong_answer":"3(2x + 9)","correct_answer":"3(2x + 3)"}'::jsonb, 'Forgets the bracket multiplies every term.', 'The answer 3(2x + 9) as a wrong option, with a reason that names the idea.', 'Divide every term by 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_HCF.M_ONE_LEFT_OUT', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_HCF', 'Leaves nothing in place of a term that equals the factor.', '{"question":"Factorise 5x + 5","wrong_answer":"5(x)","correct_answer":"5(x + 1)"}'::jsonb, 'Thinks a term divided by itself leaves nothing.', 'The answer 5(x) as a wrong option, with a reason that names the idea.', '5 ÷ 5 = 1: write the 1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_LETTERS.M_LETTER_FACTOR_MISSED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_LETTERS', 'Takes out only the number when a letter is common too.', '{"question":"Factorise 3x² + 6x fully","wrong_answer":"3(x² + 2x)","correct_answer":"3x(x + 2)"}'::jsonb, 'Looks for common numbers only.', 'The answer 3(x² + 2x) as a wrong option, with a reason that names the idea.', 'Both terms have an x: take it out too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_LETTERS.M_POWER_NOT_REDUCED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_LETTERS', 'Keeps the full power inside the bracket after taking out a letter.', '{"question":"Factorise 3x² + 6x","wrong_answer":"3x(x² + 2)","correct_answer":"3x(x + 2)"}'::jsonb, 'Does not divide the power.', 'The answer 3x(x² + 2) as a wrong option, with a reason that names the idea.', 'x² ÷ x = x.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_LETTERS.M_UNLIKE_TERMS_COMBINED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_LETTERS', 'Adds unlike terms into one before factorising.', '{"question":"Simplify 2x + 3y","wrong_answer":"5xy","correct_answer":"it cannot be simplified"}'::jsonb, 'Adds every number it sees.', 'The answer 5xy as a wrong option, with a reason that names the idea.', 'Only like terms can be added.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_LETTERS.M_LETTER_ONE_LEFT_OUT', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_LETTERS', 'Leaves nothing for a term that is the factor itself.', '{"question":"Factorise x² + x","wrong_answer":"x(x)","correct_answer":"x(x + 1)"}'::jsonb, 'Thinks x ÷ x leaves nothing.', 'The answer x(x) as a wrong option, with a reason that names the idea.', 'x ÷ x = 1: write the 1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_SIMPLIFY.M_ONLY_X_TERM_DIVIDED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_SIMPLIFY', 'Divides only the letter term of the top by the bottom.', '{"question":"Simplify (6x + 9)/3","wrong_answer":"2x + 9","correct_answer":"2x + 3"}'::jsonb, 'Forgets the bottom divides the whole top.', 'The answer 2x + 9 as a wrong option, with a reason that names the idea.', 'Every part of the top is divided by 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_SIMPLIFY.M_CANCEL_ACROSS_PLUS', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_SIMPLIFY', 'Cancels a number that is only part of a sum on the top.', '{"question":"Simplify (x + 3)/3","wrong_answer":"x","correct_answer":"it cannot be simplified to x (it is x/3 + 1)"}'::jsonb, 'Cancels as if the top were a product.', 'The answer x as a wrong option, with a reason that names the idea.', 'Only common factors cancel; 3 is not a factor of x + 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_SIMPLIFY.M_CANCEL_LETTER_IN_SUM', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_SIMPLIFY', 'Cancels a letter on the top with one on the bottom when the top is a sum.', '{"question":"Simplify (x + 2)/x","wrong_answer":"2","correct_answer":"1 + 2/x"}'::jsonb, 'Crosses out matching letters.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'x is not a factor of the whole top.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_SIMPLIFY.M_NOT_FACTORISED_FIRST', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_SIMPLIFY', 'Leaves a fraction unsimplified because the common bracket is hidden.', '{"question":"Simplify (4x + 8)/(x + 2)","wrong_answer":"(4x + 8)/(x + 2)","correct_answer":"4"}'::jsonb, 'Does not factorise the top.', 'The answer (4x + 8)/(x + 2) as a wrong option, with a reason that names the idea.', '4x + 8 = 4(x + 2): now cancel (x + 2).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB.M_ALG_TOPS_BOTTOMS_ADDED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB', 'Adds tops together and bottoms together.', '{"question":"x/2 + x/3","wrong_answer":"2x/5","correct_answer":"5x/6"}'::jsonb, 'Copies the rule for multiplying fractions.', 'The answer 2x/5 as a wrong option, with a reason that names the idea.', 'Use a common denominator, 6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB.M_DENOMINATOR_ONLY_CHANGED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB', 'Changes the bottoms to the common denominator but not the tops.', '{"question":"x/2 + x/3","wrong_answer":"2x/6","correct_answer":"5x/6"}'::jsonb, 'Forgets each top must be multiplied too.', 'The answer 2x/6 as a wrong option, with a reason that names the idea.', 'x/2 = 3x/6 and x/3 = 2x/6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB.M_ALG_FRACTIONS_NOT_ADDABLE', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB', 'Believes algebraic fractions cannot be added.', '{"question":"Can x/2 + x/3 be written as one fraction?","wrong_answer":"No","correct_answer":"Yes: 5x/6"}'::jsonb, 'Thinks letters stop fractions being added.', 'The answer No as a wrong option, with a reason that names the idea.', 'They add like number fractions once the bottoms match.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB.M_ALG_DENOMINATORS_ADDED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB', 'Adds the bottom numbers when solving with fractions.', '{"question":"x/3 + x/4 = 7","wrong_answer":"x = 49","correct_answer":"x = 12"}'::jsonb, 'Treats x/3 + x/4 as x/7.', 'The answer x = 49 as a wrong option, with a reason that names the idea.', 'Common denominator 12: 7x/12 = 7.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB.M_ONE_FRACTION_SOLVED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB', 'Solves using only the first fraction.', '{"question":"x/3 + x/4 = 7","wrong_answer":"x = 21","correct_answer":"x = 12"}'::jsonb, 'Ignores the second term.', 'The answer x = 21 as a wrong option, with a reason that names the idea.', 'Both parts of the shamba count.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB.M_LCM_MULTIPLIED_NOT_DIVIDED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB', 'Multiplies both sides by the common denominator and stops.', '{"question":"x/3 + x/4 = 7","wrong_answer":"x = 84","correct_answer":"x = 12"}'::jsonb, 'Forgets that 7x is left, not x.', 'The answer x = 84 as a wrong option, with a reason that names the idea.', 'Times 12 gives 4x + 3x = 84, so 7x = 84.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB.M_SUBTRACT_SIGN_NOT_SPREAD', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB', 'Takes away only the first term of a top that is subtracted.', '{"question":"x/2 - (x - 1)/3","wrong_answer":"(x - 2)/6","correct_answer":"(x + 2)/6"}'::jsonb, 'Leaves out the bracket.', 'The answer (x - 2)/6 as a wrong option, with a reason that names the idea.', '3x - 2(x - 1) = 3x - 2x + 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_POSITIVE.M_FIXED_TIMES_VARIABLE', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_POSITIVE', 'Multiplies the whole expression by the value.', '{"question":"F = 50 + 30d; d = 6","wrong_answer":"480","correct_answer":"230"}'::jsonb, 'Puts the fixed amount and the rate together.', 'The answer 480 as a wrong option, with a reason that names the idea.', 'Only the 30d part uses the distance.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
